describe('Error Boundary Tests', () => {
    beforeEach(() => {
        cy.visit('/'); // Adjust the URL to your application's base URL
    });

    it('should display the fallback screen when a UI crash occurs', () => {
        // Simulate a UI crash
        cy.intercept('GET', '/api/data', { statusCode: 500 }).as('getData');
        cy.visit('/crash-route'); // Adjust to the route that triggers the crash
        cy.wait('@getData');

        // Assert that the fallback screen is displayed
        cy.get('.fallback-screen').should('be.visible');
        cy.contains('Something went wrong. Please try again later.').should('be.visible');
    });

    it('should not display the fallback screen when the UI is functioning correctly', () => {
        // Simulate a successful API response
        cy.intercept('GET', '/api/data', { fixture: 'data.json' }).as('getData');
        cy.visit('/'); // Adjust to the route that loads the data
        cy.wait('@getData');

        // Assert that the main content is displayed
        cy.get('.main-content').should('be.visible');
        cy.contains('Welcome to the application!').should('be.visible');
    });
});
